 Vector3 probeMapFocus;float probeMapYaw=.25f,probeMapPitch=1.03f,probeMapScale=24;Rectangle probeMapViewport;bool probeMapDrag,probeMapRight,probeMapMaximized,probeMapShowCelestials=true;string probeMapDragAxis="",probeMapDragProbe="";Vector2 probeMapDown,probeMapLast;Vector3 probeMapStart;float probeMapStartRange,probeMapStartSpacing;Rectangle probeMapPrevious;DateTime probeMapClickTime;
