 void ProbeMapRing(Vector3 center,float radius,int plane,Color color){Vector2? last=null;for(int i=0;i<=64;i++){float a=i*MathF.Tau/64;Vector3 offset=plane==0?new(MathF.Cos(a),0,MathF.Sin(a)):plane==1?new(MathF.Cos(a),MathF.Sin(a),0):new(0,MathF.Cos(a),MathF.Sin(a));var point=ProbeMapPoint(center+offset*radius);if(last.HasValue)ui.Line(last.Value,point,color);last=point;}}
