 void DrawProbeMap(DesktopWindow w){var r=w.Bounds;int y=r.Y+35;ui.Button(new(r.X+9,y,100,24),"TOP / 3D",()=>probeMapPitch=Math.Abs(probeMapPitch-MathF.PI/2)<.1f?.95f:MathF.PI/2,"Toggle probe map top view");ui.Button(new(r.X+115,y,100,24),"FOCUS",()=>probeMapFocus=world.ProbeCenter,"Focus probe formation");ui.Button(new(r.X+221,y,100,24),"SYSTEM",()=>{probeMapFocus=Vector3.Zero;probeMapScale=12;},"Reset probe map view");ui.Button(new(r.X+327,y,100,24),"LAYERS",()=>probeMapShowCelestials=!probeMapShowCelestials,"Toggle probe map celestials",probeMapShowCelestials);ui.Button(new(r.X+433,y,105,24),"MAXIMIZE",ToggleProbeMapFullscreen,"Maximize probe system map");ui.Button(new(r.Right-118,y,108,24),"SCANNER",()=>EnsureWindow(ViewMode.Scanner),"Open probe scanner");probeMapViewport=new(r.X+2,r.Y+65,r.Width-4,r.Height-101);probeMapHits.Clear();ui.Box(probeMapViewport,new Color(5,15,19,249));ui.Layer(Matrix.Identity,probeMapViewport);
 var zero=ProbeMapPoint(Vector3.Zero);if(probeMapShowCelestials){foreach(var c in world.Celestials.Where(c=>c.Kind==CelestialKind.Planet)){var pos=c.Position.Local/(float)SolarCatalog.AU;ProbeMapRing(Vector3.Zero,new Vector2(pos.X,pos.Z).Length(),0,new Color(38,68,68,120));var at=ProbeMapPoint(pos);ui.Circle(at,4,new Color(97,148,141),2);ui.Text(ShortSpace(c.Name,20),at.X+7,at.Y-10,new Color(120,156,151),10);probeMapHits.Add((new((int)at.X-8,(int)at.Y-8,16,16),c.Id,"Celestial"));}ui.Circle(zero,6,Gold,3);ui.Text(world.Current.Name,zero.X+10,zero.Y-15,Gold,12);foreach(var c in world.Celestials.Where(c=>c.Kind is CelestialKind.Station or CelestialKind.Stargate or CelestialKind.Wormhole)){var at=ProbeMapPoint(c.Anchor.Local/(float)SolarCatalog.AU);ui.Hex(at,5,Muted);probeMapHits.Add((new((int)at.X-7,(int)at.Y-7,14,14),c.Id,"Celestial"));}}
 foreach(var bookmark in world.Bookmarks.Where(b=>b.System==world.SystemId)){var at=ProbeMapPoint(bookmark.Position.Local/(float)SolarCatalog.AU);ui.Hex(at,5,Gold);probeMapHits.Add((new((int)at.X-7,(int)at.Y-7,14,14),bookmark.Id,"Bookmark"));}
 foreach(var site in ProbeFilteredResults()){if(site.Signal==0&&site.TargetId.Length>0)continue;var pos=new Vector3(site.EstimateX,site.EstimateY,site.EstimateZ);var at=ProbeMapPoint(pos);var col=ProbeSignalColor(site.Signal);bool selected=world.ProbeSelection==site.Id;float uncertainty=site.Signal<=0?1.8f:Math.Max(.08f,site.DeviationAU);if(site.ResultShape=="Sphere"&&site.Signal<100)ProbeMapSphere(pos,uncertainty,new Color(col,selected?.65f:.25f));else if(site.ResultShape=="Circle"&&site.Signal<100)ProbeMapRing(pos,uncertainty,0,new Color(col,.65f));else if(site.ResultShape=="Two points"&&site.Signal<100){var second=ProbeMapPoint(pos+new Vector3(uncertainty,0,-uncertainty));ui.Circle(second,5,col,2);}ui.Line(at-new Vector2(5,5),at+new Vector2(5,5),col,2);ui.Line(at+new Vector2(5,-5),at+new Vector2(-5,5),col,2);if(selected){ui.Circle(at,13,col,2);if(world.ProbeScanLeft>0&&world.ProbeJob!=null)ui.Arc(at,17,-MathF.PI/2,MathF.Tau*(1-world.ProbeScanLeft/world.ProbeJob.Duration),Cyan,2);}ui.Text(DemoWorld.ProbeSignatureCode(site)+$" {site.Signal:0.0}%",at.X+13,at.Y-8,col,10);probeMapHits.Add((new((int)at.X-12,(int)at.Y-12,24,24),site.Id,"Result"));}
 foreach(var p in world.ActiveScanProbes){var pos=DemoWorld.ProbePlannedAU(p);bool selected=selectedProbe==p.Id;ProbeMapSphere(pos,p.PlanRange,new Color(99,187,201,selected?125:58));var at=ProbeMapPoint(pos);ui.Circle(at,selected?5:3,Cyan,2);probeMapHits.Add((new((int)at.X-8,(int)at.Y-8,16,16),p.Id,"Probe"));if(p.Planned&&Vector3.Distance(DemoWorld.ProbeActualAU(p),pos)>.01f&&world.ProbeScanLeft<=0)ui.Line(ProbeMapPoint(DemoWorld.ProbeActualAU(p)),at,new Color(57,86,97,60));}
 if(world.ActiveScanProbes.Any()){var center=ProbeMapPoint(world.ProbeCenter);var face=new Rectangle((int)center.X-10,(int)center.Y-10,20,20);ui.Box(face,new Color(145,222,229,180));ui.Border(face,White);probeMapHits.Add((face,"","XZ"));foreach(var axis in new[]{("X",Vector3.UnitX,new Color(214,107,100)),("Y",Vector3.UnitY,new Color(130,205,150)),("Z",Vector3.UnitZ,new Color(102,163,215))}){var end=ProbeMapPoint(world.ProbeCenter+axis.Item2*(55/probeMapScale));ui.Line(center,end,axis.Item3,2);var dir=end-center;if(dir.LengthSquared()>1){dir.Normalize();var side=new Vector2(-dir.Y,dir.X);ui.Line(end,end-dir*10+side*5,axis.Item3,2);ui.Line(end,end-dir*10-side*5,axis.Item3,2);}ui.Text(axis.Item1,end.X+5,end.Y-8,axis.Item3,11);probeMapHits.Add((new((int)end.X-11,(int)end.Y-11,22,22),"",axis.Item1));}var vertical=new Rectangle((int)center.X+12,(int)center.Y+12,15,15);ui.Border(vertical,Cyan);probeMapHits.Add((vertical,"","XY"));}
 ui.ResetLayer();ui.Text($"{world.Current.Name}  |  {world.ProbeFormation}  |  {world.ProbeRange:0.##} AU  |  center {world.ProbeCenter.X:0.00}, {world.ProbeCenter.Y:0.00}, {world.ProbeCenter.Z:0.00} AU",r.X+12,r.Bottom-29,Cyan,11);ui.Text("Drag cube/axes: move | Shift: single probe | Alt: range | Ctrl: spacing | Empty drag: rotate | Right drag: pan | Wheel: zoom",r.X+12,r.Bottom-13,Muted,9);
 }
 bool ProbeMapInput(MouseState m,KeyboardState keys){if(ProbeScannerInput(m))return true;var window=WindowAt(mouse);bool inside=window?.Kind==ViewMode.ProbeMap&&probeMapViewport.Contains(mouse.ToPoint());bool leftDown=m.LeftButton==ButtonState.Pressed&&oldMouse.LeftButton==ButtonState.Released,rightDown=m.RightButton==ButtonState.Pressed&&oldMouse.RightButton==ButtonState.Released;bool leftUp=m.LeftButton==ButtonState.Released&&oldMouse.LeftButton==ButtonState.Pressed,rightUp=m.RightButton==ButtonState.Released&&oldMouse.RightButton==ButtonState.Pressed;
 if(!probeMapDrag&&!inside)return false;if(context||spaceMenu!=null)return false;int wheel=m.ScrollWheelValue-oldMouse.ScrollWheelValue;if(inside&&wheel!=0){if(keys.IsKeyDown(Keys.LeftAlt)||keys.IsKeyDown(Keys.RightAlt))world.SetProbeRange(world.ProbeRange*MathF.Pow(2,wheel/120));else probeMapScale=Math.Clamp(probeMapScale*MathF.Pow(1.2f,wheel/120),1,65536);return true;}
 if(!probeMapDrag&&(leftDown||rightDown)){probeMapDrag=true;probeMapRight=rightDown;probeMapDown=probeMapLast=mouse;probeMapStart=world.ProbeCenter;probeMapStartRange=world.ProbeRange;probeMapStartSpacing=1;probeMapDragAxis="Rotate";probeMapDragProbe="";var hit=probeMapHits.LastOrDefault(h=>h.Rect.Contains(mouse.ToPoint()));if(hit.Rect.Width>0){if(hit.Kind=="Result"){var site=world.UtilitySites.First(s=>s.Id==hit.Id);world.ProbeSelection=site.Id;probeMapDragAxis="Result";}else if(hit.Kind is "Celestial" or "Bookmark"){world.SelectedId=hit.Id;probeMapDragAxis="Celestial";}else if(hit.Kind=="Probe"){selectedProbe=hit.Id;probeMapDragProbe=hit.Id;probeMapDragAxis="XZ";if(keys.IsKeyDown(Keys.LeftShift)||keys.IsKeyDown(Keys.RightShift))probeMapStart=DemoWorld.ProbePlannedAU(world.ScanProbes.First(p=>p.Id==hit.Id));}else probeMapDragAxis=hit.Kind;}
 return true;}
 if(probeMapDrag){var delta=mouse-probeMapDown;var recent=mouse-probeMapLast;if(m.LeftButton==ButtonState.Pressed||m.RightButton==ButtonState.Pressed){if(probeMapRight)probeMapFocus-=ProbeMapDelta(recent);else if(probeMapDragAxis=="Rotate"){probeMapYaw+=recent.X*.007f;probeMapPitch=Math.Clamp(probeMapPitch+recent.Y*.007f,-MathF.PI/2,MathF.PI/2);}else if(probeMapDragAxis is not("Result" or "Celestial")){bool alt=keys.IsKeyDown(Keys.LeftAlt)||keys.IsKeyDown(Keys.RightAlt),ctrl=keys.IsKeyDown(Keys.LeftControl)||keys.IsKeyDown(Keys.RightControl),shift=keys.IsKeyDown(Keys.LeftShift)||keys.IsKeyDown(Keys.RightShift);if(alt){float range=probeMapStartRange*MathF.Pow(2,MathF.Round(delta.X/45));if(shift&&probeMapDragProbe.Length>0){var p=world.ScanProbes.First(p=>p.Id==probeMapDragProbe);world.PlanProbe(p,DemoWorld.ProbePlannedAU(p),range);world.ProbeLayoutCustomized=true;}else world.SetProbeRange(range);}else if(ctrl){float factor=Math.Clamp(MathF.Pow(2,delta.X/120),.1f,8);world.ScaleProbeSpacing(factor/probeMapStartSpacing);probeMapStartSpacing=factor;}else{var move=ProbeMapDelta(delta);if(probeMapDragAxis=="X")move=new(move.X,0,0);else if(probeMapDragAxis=="Y")move=new(0,move.Y,0);else if(probeMapDragAxis=="Z")move=new(0,0,move.Z);else if(probeMapDragAxis=="XZ")move.Y=0;else if(probeMapDragAxis=="XY")move.Z=0;if(shift&&probeMapDragProbe.Length>0)world.MoveSingleProbe(probeMapDragProbe,probeMapStart+move);else world.MoveProbeFormation(probeMapStart+move);}}probeMapLast=mouse;}
 if(leftUp||rightUp){bool click=delta.Length()<6;if(probeMapRight&&click)ProbeMapMenu();else if(click){var now=DateTime.UtcNow;bool twice=(now-probeMapClickTime).TotalMilliseconds<350;probeMapClickTime=now;if(twice&&probeMapDragAxis is "XZ" or "XY" or "X" or "Y" or "Z")probeMapFocus=world.ProbeCenter;else if(twice&&probeMapDragAxis=="Result"){var site=world.UtilitySites.FirstOrDefault(s=>s.Id==world.ProbeSelection);if(site!=null)FocusProbeEstimate(site);}}probeMapDrag=false;}return true;}return inside;}
 void ProbeMapMenu(){var hit=probeMapHits.LastOrDefault(h=>h.Rect.Contains(mouse.ToPoint()));var actions=new List<(string,Action)>();if(hit.Kind=="Probe")actions.Add(("Show Info",()=>ShowInformation("probe/"+hit.Id)));else if(hit.Id.Length>0)actions.Add(("Show Info",()=>ShowObjectInfo(hit.Id)));if(hit.Kind=="Result"){var s=world.UtilitySites.First(s=>s.Id==hit.Id);world.ProbeSelection=s.Id;actions.Add(("Center probes here",world.CenterUtilityProbes));actions.Add(("Focus result",()=>FocusProbeEstimate(s)));if(world.ProbeWarpable(s)){actions.Add(("Warp to result",()=>world.WarpUtilitySite()));actions.Add(("Save location",()=>world.BookmarkProbeResult(s.Id)));}actions.Add(("Ignore result",()=>s.Ignored=true));}else if(hit.Kind is "Celestial" or "Bookmark"){actions.Add(("Focus location",()=>{if(SolarCatalog.Resolve(world.SystemId,hit.Id) is {} c)probeMapFocus=c.Position.Local/(float)SolarCatalog.AU;else if(world.Bookmarks.FirstOrDefault(b=>b.Id==hit.Id) is {} b)probeMapFocus=b.Position.Local/(float)SolarCatalog.AU;}));actions.Add(("Warp to within 0 m",()=>world.BeginWarp(hit.Id,0)));}else if(hit.Kind=="Probe"){actions.Add(("Recover probe",()=>world.RecoverActiveProbes(hit.Id)));actions.Add(("Destroy probe",()=>world.DestroyScanProbe(hit.Id)));}actions.Add(("Focus probe formation",()=>probeMapFocus=world.ProbeCenter));actions.Add(("Spread formation",()=>world.SetProbeFormation("Spread")));actions.Add(("Pinpoint formation",()=>world.SetProbeFormation("Pinpoint")));actions.Add(("Save custom formation",()=>world.SaveProbePreset("Custom "+(world.ProbePresets.Count+1))));actions.Add(("Analyze",()=>world.AnalyzeUtilityProbes()));actions.Add(("Open probe scanner",()=>EnsureWindow(ViewMode.Scanner)));ShowPopup("System / probe map",actions);}
